<script setup lang="ts">import{onBeforeUnmount,onMounted,ref,watch}from'vue';import type{Agent}from'../../domain/agents/types';import{VoxelWorldScene,WORLD_STATIONS}from'../../infrastructure/three/scene/VoxelWorldScene';const props=defineProps<{agent:Agent}>();const emit=defineEmits<{station:[id:string]}>();const host=ref<HTMLDivElement|null>(null);let scene:VoxelWorldScene|undefined;onMounted(()=>{if(host.value)scene=new VoxelWorldScene(host.value,props.agent,id=>emit('station',id))});watch(()=>props.agent,a=>scene?.updateAgent(a),{deep:true});onBeforeUnmount(()=>scene?.dispose())</script><template><div class="space-y-2"><div class="relative h-full min-h-[480px] overflow-hidden rounded-xl border border-default bg-elevated"><div ref="host" class="absolute inset-0"/><div class="pointer-events-none absolute left-3 top-3 rounded-lg border border-default bg-default/80 px-3 py-2 backdrop-blur"><div class="text-xs text-muted">Klaus world · optional spatial navigator</div><div class="text-sm font-semibold">{{agent.name}} · {{agent.version}}</div></div></div><div class="station-grid"><button v-for="s in WORLD_STATIONS" :key="s[0]" class="station-button" @click="emit('station',s[0])">{{s[1]}}</button></div></div></template>
